//! PEM (RFC 7468) import and export for JWKs (I0, ADR 0022).
//!
//! The fixtures are **generated by OpenSSL, not by this crate**, and each one is a
//! different answer to "what is in this file?": PKCS#8 for RSA/P-256/Ed25519/X25519, SPKI
//! public halves, a PKCS#1 block, a SEC1 block, an X.509 certificate, a PKCS#8
//! password-encrypted key, a legacy `Proc-Type`/`DEK-Info` key, an RSA key below the
//! strength floor, and an RSA-PSS key whose PKCS#8 would have to lose a restriction to
//! become a JWK. PEM is the format where implementations decide how permissive to be, so
//! most of what this file pins are decisions rather than round-trips.

use jose_rs::jwk::{self, pem};
use jose_rs::jws::compact;
use jose_rs::{JoseHeader, JwsAlgorithm};

fn sign_and_verify(private_pem: &str, public_pem: &str, alg: JwsAlgorithm) {
    let mut private = pem::jwk_from_pem(private_pem).expect("private PEM imports");
    let public = pem::jwk_from_pem(public_pem).expect("public PEM imports");
    assert!(private.d.is_some(), "imported key kept its private part");
    assert!(public.d.is_none(), "SPKI import is public-only");
    // `sign_with_jwk` reads the algorithm from the key, and PEM carries no `alg`, so an
    // imported key has to be pinned by the caller — the file does not get to choose.
    private.alg = Some(alg.as_str().to_string());
    let header = JoseHeader::new(alg.as_str());
    let token = compact::sign_with_jwk(&private, b"pem fixture", &header).expect("sign");
    let payload = compact::verify_with_jwk(&public, &token).expect("verify with the other file");
    assert_eq!(payload, b"pem fixture");
}

#[test]
fn openssl_rsa_pkcs8_and_spki_round_trip_and_sign() {
    sign_and_verify(RSA_PKCS8, RSA_SPKI, JwsAlgorithm::RS256);
}

#[test]
fn openssl_ecdsa_p256_pkcs8_and_spki_round_trip_and_sign() {
    sign_and_verify(EC_PKCS8, EC_SPKI, JwsAlgorithm::ES256);
}

#[test]
fn openssl_ed25519_pkcs8_and_spki_round_trip_and_sign() {
    sign_and_verify(ED_PKCS8, ED_SPKI, JwsAlgorithm::EdDSA);
}

#[test]
fn generated_keys_round_trip_through_both_exports() {
    // Generated here rather than by OpenSSL, so the export path is exercised against keys
    // this crate built (and so a fixture cannot go stale).
    for curve in ["P-256", "P-384", "P-521"] {
        let key = jwk::generate_ec(curve).expect("generate");
        let private = pem::private_pem_from_jwk(&key).expect("private export");
        let public = pem::public_pem_from_jwk(&key).expect("public export");
        assert!(private.starts_with("-----BEGIN PRIVATE KEY-----"));
        assert!(public.starts_with("-----BEGIN PUBLIC KEY-----"));
        let back = pem::jwk_from_pem(&private).expect("re-import");
        assert_eq!(back.d, key.d, "{curve}: private material survives the trip");
        assert_eq!(
            back.crv, key.crv,
            "{curve}: curve is read from the DER, not assumed"
        );
        let pub_back = pem::jwk_from_pem(&public).expect("re-import public");
        assert_eq!(
            pub_back.to_json().unwrap(),
            key.to_public_jwk().to_json().unwrap(),
            "{curve}: public export re-imports to the same public JWK"
        );
    }
    let ed = jwk::generate_ed25519().expect("generate ed25519");
    let back = pem::jwk_from_pem(&pem::private_pem_from_jwk(&ed).unwrap()).unwrap();
    assert_eq!(back.to_json().unwrap(), ed.to_json().unwrap());
}

#[test]
fn equivalent_imports_have_matching_thumbprints() {
    // The acceptance criterion for "equivalent import formats": a key read from PKCS#8
    // and the same key read from SPKI have the same *public* thumbprint, which compares
    // the canonical JWK members rather than the file bytes.
    let from_private = pem::jwk_from_pem(RSA_PKCS8).unwrap();
    let from_public = pem::jwk_from_pem(RSA_SPKI).unwrap();
    assert_eq!(
        jwk::thumbprint::thumbprint_sha256(&from_private.to_public_jwk()).unwrap(),
        jwk::thumbprint::thumbprint_sha256(&from_public).unwrap()
    );
}

#[test]
fn jwk_metadata_does_not_survive_the_trip() {
    // PEM has nowhere to put `kid`, `use` or `alg`, and inventing a header for them would
    // produce a file no one else reads. Pinning that as intended behaviour.
    let mut key = jwk::generate_ec("P-256").unwrap();
    key.kid = Some("key-1".into());
    key.alg = Some("ES256".into());
    let back = pem::jwk_from_pem(&pem::private_pem_from_jwk(&key).unwrap()).unwrap();
    assert_eq!(back.d, key.d);
    assert_eq!(back.kid, None, "kid is not encoded in PKCS#8");
    assert_eq!(back.alg, None, "and neither is the pinned algorithm");
}

#[test]
fn private_export_requires_private_material() {
    let public = jwk::generate_ed25519().unwrap().to_public_jwk();
    let err = pem::private_pem_from_jwk(&public).unwrap_err().to_string();
    assert!(err.contains("private part"), "{err}");
    // …and the public exporter, on a *private* key, can only ever emit the public half.
    let private = jwk::generate_ed25519().unwrap();
    let emitted = pem::public_pem_from_jwk(&private).unwrap();
    assert!(emitted.starts_with("-----BEGIN PUBLIC KEY-----"));
    assert!(!emitted.contains("PRIVATE KEY-----\nMI"), "{emitted}");
    assert_eq!(
        pem::jwk_from_pem(&emitted).unwrap().to_json().unwrap(),
        private.to_public_jwk().to_json().unwrap()
    );
}

#[test]
fn x25519_public_export_is_refused_by_name() {
    // The backend hands back X25519's bare `u` coordinate for a "public component". The
    // refusal has to be specific, because the alternative is writing a file that claims
    // to be SPKI and is not.
    let key = jwk::generate_x25519().unwrap();
    let err = pem::public_pem_from_jwk(&key).unwrap_err().to_string();
    assert!(err.contains("X25519") && err.contains("SPKI"), "{err}");
    // Ed25519, the other OKP curve, exports normally — the distinction is the curve.
    let ed = jwk::generate_ed25519().unwrap();
    assert!(pem::public_pem_from_jwk(&ed).is_ok());
}

#[test]
fn two_blocks_are_refused_with_a_count() {
    let both = format!("{ED_SPKI}{ED_SPKI}");
    let err = pem::jwk_from_pem(&both).unwrap_err().to_string();
    assert!(err.contains("2 blocks"), "{err}");
    // A certificate chain is the legitimate multi-block case, and it gets a
    // certificate-specific entry point rather than a relaxation of this rule.
    let three = format!("{CERT}{CERT}{CERT}");
    assert!(pem::jwk_from_pem(&three)
        .unwrap_err()
        .to_string()
        .contains("3 blocks"));
}

#[test]
fn preamble_and_trailing_text_are_refused_whitespace_is_not() {
    // RFC 7468 permits a preamble. Reading a key out of a document that happens to contain
    // one is how "which key did they mean?" becomes a silent decision.
    let pre = format!("here is the key I promised:\n{ED_SPKI}");
    assert!(pem::jwk_from_pem(&pre)
        .unwrap_err()
        .to_string()
        .contains("before the"));
    let trail = format!("{ED_SPKI}and that is all of it");
    assert!(pem::jwk_from_pem(&trail)
        .unwrap_err()
        .to_string()
        .contains("after the"));
    // Surrounding blank space is normal in files that were edited by hand.
    let padded = format!("\n\n{ED_SPKI}\n   \n");
    assert!(pem::jwk_from_pem(&padded).is_ok());
    // CRLF line endings are accepted (the files exist); a lone CR inside the body is not.
    let crlf = ED_SPKI.replace('\n', "\r\n");
    assert!(pem::jwk_from_pem(&crlf).is_ok());
}

#[test]
fn structurally_broken_armor_is_refused() {
    // Missing END boundary.
    let no_end = ED_SPKI.replace("-----END PUBLIC KEY-----\n", "");
    assert!(pem::jwk_from_pem(&no_end)
        .unwrap_err()
        .to_string()
        .contains("PEM"));
    // Non-canonical base64: the body must decode to whole octets.
    let bad = "-----BEGIN PUBLIC KEY-----\nQQ\n-----END PUBLIC KEY-----\n";
    assert!(pem::jwk_from_pem(bad)
        .unwrap_err()
        .to_string()
        .contains("PEM"));
    // Trailing bits in the last group.
    let bits = "-----BEGIN PUBLIC KEY-----\nQ===\n-----END PUBLIC KEY-----\n";
    assert!(pem::jwk_from_pem(bits)
        .unwrap_err()
        .to_string()
        .contains("PEM"));
    // A label in lower case is a different label.
    let lower = ED_SPKI.replace("PUBLIC KEY", "public key");
    assert!(pem::jwk_from_pem(&lower)
        .unwrap_err()
        .to_string()
        .contains("block"));
    // An empty body.
    let empty = "-----BEGIN PUBLIC KEY-----\n\n-----END PUBLIC KEY-----\n";
    assert!(pem::jwk_from_pem(empty).is_err());
    // And the input is size-bounded like everything else that is parsed.
    let huge = format!(
        "-----BEGIN PUBLIC KEY-----\n{}\n-----END PUBLIC KEY-----\n",
        "A".repeat(4_000_000)
    );
    assert!(pem::jwk_from_pem(&huge)
        .unwrap_err()
        .to_string()
        .contains("size"));
}

#[test]
fn other_pem_labels_are_refused_by_name() {
    // Each of these is a different structure. The label is the only place the difference
    // is written, so guessing from the bytes is exactly what must not happen.
    for (pem_text, label, hint) in [
        (RSA_PKCS1, "RSA PRIVATE KEY", "PKCS#1"),
        (EC_SEC1, "EC PRIVATE KEY", "SEC1"),
        (CERT, "CERTIFICATE", "certificate"),
    ] {
        let err = pem::jwk_from_pem(pem_text).unwrap_err().to_string();
        assert!(err.contains(label), "{label}: {err}");
        assert!(err.contains(hint), "{label}: {err}");
    }
    // A password-encrypted PKCS#8 is a *label* case, and a legacy RFC 1423 key is a
    // *header* case; both say "this is encrypted" rather than failing as corruption.
    let enc = pem::jwk_from_pem(EC_ENCRYPTED_PBKDF2)
        .unwrap_err()
        .to_string();
    assert!(enc.contains("ENCRYPTED PRIVATE KEY"), "{enc}");
    let legacy = pem::jwk_from_pem(RSA_LEGACY).unwrap_err().to_string();
    assert!(legacy.contains("password-encrypted"), "{legacy}");
}

#[test]
fn explicit_format_entry_points_refuse_the_other_label() {
    // A caller who asked for a private key and is handed a public one should find out from
    // the error, not by downstream confusion.
    assert!(pem::jwk_from_pkcs8_pem(ED_PKCS8).is_ok());
    assert!(pem::jwk_from_spki_pem(ED_SPKI).is_ok());
    let wrong1 = pem::jwk_from_pkcs8_pem(ED_SPKI).unwrap_err().to_string();
    assert!(
        wrong1.contains("expected a PEM \"PRIVATE KEY\""),
        "{wrong1}"
    );
    let wrong2 = pem::jwk_from_spki_pem(ED_PKCS8).unwrap_err().to_string();
    assert!(wrong2.contains("expected a PEM \"PUBLIC KEY\""), "{wrong2}");
    // …and both still refuse the labels they do not parse at all.
    assert!(pem::jwk_from_pkcs8_pem(CERT).is_err());
    assert!(pem::jwk_from_spki_pem(RSA_PKCS1).is_err());
}

#[test]
fn der_level_rules_still_apply_through_the_armor() {
    // PEM is a wrapper: the DER importer's own refusals must survive being reached through
    // it, or the armor would be a way around them.

    // An RSA-PSS key's PKCS#8 cannot become a generic RSA JWK without discarding its
    // PSS-only restriction.
    let err = pem::jwk_from_pem(RSA_PSS_PKCS8).unwrap_err().to_string();
    assert!(
        err.to_lowercase().contains("pss") || err.to_lowercase().contains("rsa"),
        "{err}"
    );

    // A 1024-bit RSA key is below this crate's modulus floor. The PEM path must not be an
    // easier way in than the DER path.
    assert!(
        pem::jwk_from_pem(RSA1024_PKCS8).is_err(),
        "weak key still refused"
    );
    assert!(pem::jwk_from_pem(RSA_PKCS8).is_ok(), "2048-bit accepted");

    // X25519's PKCS#8 is valid DER but outside the signature families this crate imports.
    let x25519 = pem::jwk_from_pem(X25519_PKCS8);
    match x25519 {
        // Either an outright refusal, or an OKP import that cannot be used as a signing
        // key. "It parsed" is never the whole answer.
        Err(err) => assert!(
            err.to_string().contains("X25519") || err.to_string().contains("PKCS#8"),
            "{err}"
        ),
        Ok(imported) => {
            let header = JoseHeader::new("EdDSA");
            assert!(
                compact::sign_with_jwk(&imported, b"x", &header).is_err(),
                "an X25519 key must not sign"
            );
        }
    }
}

#[test]
fn a_key_file_is_not_a_jwk_file() {
    // The other direction of the same discipline: JWK JSON is not PEM.
    let key = jwk::generate_ed25519().unwrap();
    assert!(pem::jwk_from_pem(&key.to_json().unwrap()).is_err());
    // And a PEM body whose DER does not match its label is refused rather than
    // reinterpreted: an Ed25519 SPKI wearing the RSA-shaped label of a PKCS#8 private key.
    let mismatched = ED_SPKI
        .replace("BEGIN PUBLIC KEY", "BEGIN PRIVATE KEY")
        .replace("END PUBLIC KEY", "END PRIVATE KEY");
    assert!(pem::jwk_from_pem(&mismatched).is_err());
}

#[test]
fn exported_pem_is_stable_and_well_formed() {
    let key = jwk::generate_ec("P-256").unwrap();
    let once = pem::private_pem_from_jwk(&key).unwrap();
    let twice = pem::private_pem_from_jwk(&key).unwrap();
    assert_eq!(once, twice, "export is deterministic");
    // Canonical RFC 7468 shape: label line, 64-column base64, terminating newline.
    let lines: Vec<&str> = once.lines().collect();
    assert_eq!(lines[0], "-----BEGIN PRIVATE KEY-----");
    assert_eq!(lines[lines.len() - 1], "-----END PRIVATE KEY-----");
    for line in &lines[1..lines.len() - 1] {
        assert!(
            line.len() <= 64,
            "line longer than RFC 7468's wrap: {}",
            line.len()
        );
        assert!(
            line.chars()
                .all(|c| c.is_ascii_alphanumeric() || "+/=".contains(c)),
            "{line}"
        );
    }
    // Nothing in a Debug rendering of a JWK leaks the PEM it came from.
    let imported = pem::jwk_from_pem(RSA_PKCS8).unwrap();
    let debug = format!("{imported:?}");
    assert!(
        !debug.contains(&imported.d.clone().unwrap_or_default()),
        "private material in Debug"
    );
}

