#[test]
fn private_export_is_the_form_peers_read() {
    // The backend's Ed25519 export is an `OneAsymmetricKey` (version 1) carrying the public
    // key as an attribute. That is legal, OpenSSL reads it, and `cryptography` refuses it —
    // measured, not assumed. The attribute is redundant (the public key is computed from
    // the seed), so the export normalizes to `PrivateKeyInfo` (version 0), which is what
    // OpenSSL and every JOSE library emit for these keys.
    let ed = jwk::generate_ed25519().unwrap();
    let pem_text = pem::private_pem_from_jwk(&ed).unwrap();
    let der = pem::jwk_from_pem(&pem_text).unwrap();
    assert_eq!(der.d, ed.d, "normalizing did not change the key");
    let body: String = pem_text
        .lines()
        .filter(|l| !l.starts_with("-----"))
        .collect();
    let der_bytes = base64_decode(&body);
    assert_eq!(pkcs8_version(&der_bytes), 0, "exported PKCS#8 is version 0");
    assert!(
        der_bytes
            .windows(7)
            .any(|w| w == [0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70]),
        "Ed25519 algorithm identifier is present"
    );
    // RSA and EC already had no attribute and pass through byte for byte.
    for curve in ["P-256", "P-384"] {
        let key = jwk::generate_ec(curve).unwrap();
        let text = pem::private_pem_from_jwk(&key).unwrap();
        let bytes = base64_decode(
            &text
                .lines()
                .filter(|l| !l.starts_with("-----"))
                .collect::<String>(),
        );
        assert_eq!(pkcs8_version(&bytes), 0, "{curve} is version 0");
    }
}

#[test]
fn version_one_oneasymmetrickey_still_imports() {
    // Reading is not writing. A peer that sends the version-1 form (OpenSSL does for some
    // key types) is read fine — refusing to *emit* it is an interop choice, not a claim
    // that the form is malformed. Fixture: an Ed25519 OneAsymmetricKey with the publicKey
    // attribute, as produced by the `ed25519` crate's own encoder.
    const V1: &str = r#"-----BEGIN PRIVATE KEY-----
MFECAQEwBQYDK2VwBCIEIJdlBRIwgujc+6TL123OgQSniTR+yVzXwcFxH+goOUMa
gSEAG6Lv9z6faPVTABAMOIKJUE6lrQjiWyww0VUdbZrg7Es=
-----END PRIVATE KEY-----
"#;
    let imported = pem::jwk_from_pem(V1).expect("version 1 imports");
    assert_eq!(imported.kty, "OKP");
    assert_eq!(imported.crv.as_deref(), Some("Ed25519"));
    assert_eq!(
        imported.d.as_deref(),
        Some("l2UFEjCC6Nz7pMvXbc6BBKeJNH7JXNfBwXEf6Cg5Qxo")
    );
    assert_eq!(
        imported.x.as_deref(),
        Some("G6Lv9z6faPVTABAMOIKJUE6lrQjiWyww0VUdbZrg7Es")
    );
    // …and re-exporting it produces the portable form, which imports to the same key.
    let again = pem::private_pem_from_jwk(&imported).unwrap();
    assert_eq!(pem::jwk_from_pem(&again).unwrap().d, imported.d);
}

/// The `version` INTEGER of a PKCS#8 `PrivateKeyInfo` / `OneAsymmetricKey` DER.
///
/// Parsed rather than read at a fixed offset because EC keys are long enough that the
/// outer SEQUENCE's length takes two bytes.
fn pkcs8_version(der: &[u8]) -> u8 {
    assert_eq!(der[0], 0x30, "outer SEQUENCE");
    let length_octets = if der[1] & 0x80 == 0 { 0 } else { der[1] & 0x7f } as usize;
    let start = 2 + length_octets;
    assert_eq!(&der[start..start + 2], &[0x02, 0x01], "version INTEGER");
    der[start + 2]
}

/// Base64-decode a PEM body without pulling in a decoder dependency for one test.
fn base64_decode(text: &str) -> Vec<u8> {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut bits = 0u32;
    let mut acc = 0u32;
    let mut out = Vec::new();
    for byte in text.bytes() {
        if byte == b'=' {
            break;
        }
        let value = ALPHABET
            .iter()
            .position(|c| *c == byte)
            .unwrap_or_else(|| panic!("not base64: {}", byte as char)) as u32;
        acc = (acc << 6) | value;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
        }
    }
    out
}
